export function validateAuthorityResolution(resolution) {
  if (!conforms(resolution, AUTHORITY_DEFINITION.input_schemas.outcome.properties.authority_resolution)) fail('AUTHORITY_RESOLUTION_INVALID');
  return structuredClone(resolution);
