        if (typed.request.kind !== 'change-request' || typed.request.parent.number !== pr.number) fail('CURRENT_CHANGE_REQUEST_MISSING');
        if (typed.request.branch !== pr.head.ref) fail('STARTING_STATE_MISMATCH');
