import { CONSUMER, EXECUTION_CONSUMER, EXECUTION_SLOT, executionConsumer, runnerExecutionSlot } from '../../consumer/consumer.mjs';
import { realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
